      const rawAmList = `$2`;

      function togglePanel() {
        const panel = document.getElementById('contextPanel');
        panel.classList.toggle('expanded');
        updateIframeHeight();
      }

      function updateIframeHeight() {
        setTimeout(() => {
          const bodyHeight = document.body.scrollHeight;
          if (window.parent && window.parent !== window) {
            window.parent.postMessage({ type: 'resizeIframe', height: bodyHeight }, '*');
          }
        }, 50);
      }

      function escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
      }

      function parseAmCodes(raw) {
        return raw
          .split(/[,，\s]+/)
          .map(s => s.trim())
          .filter(s => /^AM\d+$/i.test(s))
          .map(s => s.toUpperCase());
      }

      async function findEntryByKey(entries, keyToFind) {
        const keyUpper = keyToFind.toUpperCase();
        for (const entry of entries) {
          if (entry.key && Array.isArray(entry.key)) {
            for (const k of entry.key) {
              if (k.toUpperCase() === keyUpper) {
                return entry;
              }
            }
          }
        }
        return null;
      }

      function renderMemoryItem(amCode, entry) {
        if (!entry) {
          return `
            <div class="memory-item">
              <div class="memory-header">
                <span class="memory-id">${amCode}</span>
              </div>
            </div>
          `;
        }
        const title = entry.comment || '无标题';
        const content = entry.content || '（无内容）';
        return `
          <div class="memory-item">
            <div class="memory-header">
              <span class="memory-id">${amCode}</span>
              <span class="memory-title">${escapeHtml(title)}</span>
            </div>
            <div class="memory-body">${escapeHtml(content)}</div>
          </div>
        `;
      }

      function initUserInput() {
        const container = document.getElementById('userInputContent');
        const trimmed = rawUserInput.trim();
        container.innerHTML = trimmed ? escapeHtml(trimmed) : '<span style="color:#888;font-style:italic;">（无输入内容）</span>';
      }

      async function loadMemories() {
        const container = document.getElementById('memoryList');
        const loading = document.getElementById('recallLoading');
        const badge = document.getElementById('memoryBadge');

        const amCodes = parseAmCodes(rawAmList);
        badge.textContent = '记忆 ' + amCodes.length;

        if (amCodes.length === 0) {
          container.innerHTML = '';
          return;
        }

        try {
          let worldBookName = '';
          if (typeof getVariables === 'function') {
            const chatVars = await getVariables({ type: 'chat' });
            if (chatVars && chatVars.selectedWorldBook) {
              worldBookName = chatVars.selectedWorldBook;
            }
          }

          if (!worldBookName && typeof getCurrentCharPrimaryLorebook === 'function') {
            worldBookName = await getCurrentCharPrimaryLorebook();
          }

          if (!worldBookName) {
            let h = '';
            for (const c of amCodes) h += renderMemoryItem(c, null);
            container.innerHTML = h;
            updateIframeHeight();
            return;
          }

          if (typeof getLorebookEntries !== 'function') {
            let h = '';
            for (const c of amCodes) h += renderMemoryItem(c, null);
            container.innerHTML = h;
            updateIframeHeight();
            return;
          }

          const entries = await getLorebookEntries(worldBookName);

          let html = '';
          for (const amCode of amCodes) {
            const entry = await findEntryByKey(entries, amCode);
            html += renderMemoryItem(amCode, entry);
          }

          container.innerHTML = html;
          updateIframeHeight();

        } catch (error) {
          console.error('记忆召回失败:', error);
          let h = '';
          for (const c of amCodes) h += renderMemoryItem(c, null);
          container.innerHTML = h;
          updateIframeHeight();
        }
      }

      window.addEventListener('load', () => {
        initUserInput();
        updateIframeHeight();
        setTimeout(loadMemories, 300);
      });
    </script>
