          <button id="add-avatar-url-use" class="add-modal-btn" type="button">使用链接</button>
        </div>
        <div class="add-modal-error" id="add-avatar-error"></div>
        <div class="add-modal-hint">下方为角色变量 `phone_data.randomAvatars` 的头像库（点击即可使用）。</div>
        <div class="add-avatar-grid" id="add-avatar-grid"></div>
      </div>
    </div>

    <script>
      (function () {
        function resolveApiHost() {
          const candidates = [];
          try {
            candidates.push(window);
          } catch (e) {}

          try {
            let w = window;
            for (let i = 0; i < 8; i++) {
              const p = w.parent;
              if (!p || p === w) break;
              candidates.push(p);
              w = p;
            }
          } catch (e) {}

          try {
            if (window.top) candidates.push(window.top);
          } catch (e) {}

          try {
            if (window.opener) candidates.push(window.opener);
          } catch (e) {}

          function pick(c) {
            if (!c) return null;
            try {
              if (typeof c.getVariables === 'function' || typeof c.insertOrAssignVariables === 'function') return c;
            } catch (e) {}
            try {
              const th = c.TavernHelper;
              if (th && (typeof th.getVariables === 'function' || typeof th.insertOrAssignVariables === 'function')) return th;
            } catch (e) {}
            return null;
          }

          for (let i = 0; i < candidates.length; i++) {
            const api = pick(candidates[i]);
            if (api && typeof api.getVariables === 'function') return api;
          }

          for (let i = 0; i < candidates.length; i++) {
            const api = pick(candidates[i]);
            if (api && typeof api.insertOrAssignVariables === 'function') return api;
          }

          return pick(window) || window;
        }

        function resolveToastrHost() {
          const candidates = [];
          try {
            candidates.push(window);
          } catch (e) {}
          try {
            if (window.parent) candidates.push(window.parent);
          } catch (e) {}
          try {
            if (window.top) candidates.push(window.top);
          } catch (e) {}
          try {
            if (window.opener) candidates.push(window.opener);
          } catch (e) {}

          for (let i = 0; i < candidates.length; i++) {
            const c = candidates[i];
            try {
              if (c && c.toastr) return c;
            } catch (e) {}
          }
          return null;
        }

        const api = resolveApiHost();
        const toastrHost = resolveToastrHost();

        function safeGetCharVars() {
          try {
            return typeof api.getVariables === 'function' ? api.getVariables({ type: 'character' }) || {} : {};
          } catch (e) {
            return {};
          }
        }

        function safeInsertCharVars(patch) {
          if (!patch || typeof patch !== 'object') return false;
          try {
            if (typeof api.insertOrAssignVariables === 'function') {
              api.insertOrAssignVariables(patch, { type: 'character' });
              return true;
            }
          } catch (e) {}
          return false;
        }

        function hash(s) {
          s = String(s || '');
          let h = 0;
          for (let i = 0; i < s.length; i++) h += s.charCodeAt(i);
          return h;
        }

        function findByName(characters, name) {
          name = String(name || '').trim();
          if (!name || !Array.isArray(characters)) return null;
          for (let i = 0; i < characters.length; i++) {
            const c = characters[i] || {};
            if (String(c.name || '').trim() === name) return c;
          }
          for (let i = 0; i < characters.length; i++) {
            const c = characters[i] || {};
            if (String(c.nickname || '').trim() === name) return c;
          }
          return null;
        }

        function getPhoneData() {
          const vars = safeGetCharVars();
          let phoneData = (vars && vars.phone_data) || {};
          if (typeof phoneData === 'string') {
            try {
              phoneData = JSON.parse(phoneData);
            } catch (e) {
              phoneData = {};
            }
          }
          const characters = Array.isArray(phoneData.characters) ? phoneData.characters : [];
          const randomAvatars = Array.isArray(phoneData.randomAvatars) ? phoneData.randomAvatars : [];
          const backgrounds = Array.isArray(phoneData.backgrounds) ? phoneData.backgrounds : [];
          return { phoneData, characters, randomAvatars, backgrounds };
        }

        function getAvatarUrlDefault(name) {
          const { characters, randomAvatars } = getPhoneData();
          const c = findByName(characters, name);
          if (c && c.avatar) return String(c.avatar || '').trim();
          if (randomAvatars.length) return String(randomAvatars[hash(name) % randomAvatars.length] || '').trim();
          return '';
        }

        function setAvatar(el, url) {
          url = String(url || '').trim();
          if (!url) return;
          el.style.backgroundImage = "url('" + url.replace(/'/g, "\\'") + "')";
          el.setAttribute('data-add-avatar-url', url);
        }

        function pickBackground(list, name, offset) {
          if (!Array.isArray(list) || !list.length) return '';
          return String(list[(hash(name) + Number(offset || 0)) % list.length] || '').trim();
        }

        function toast(msg, type) {
          try {
            const t = (toastrHost && toastrHost.toastr) || (window && window.toastr);
            if (!t) return;
            if (type === 'error' && typeof t.error === 'function') return t.error(msg);
            if (type === 'warning' && typeof t.warning === 'function') return t.warning(msg);
            if (typeof t.success === 'function') return t.success(msg);
          } catch (e) {}
        }

        function normalizeHandle(handle) {
          handle = String(handle || '').trim();
          if (handle.charAt(0) === '@') handle = handle.slice(1).trim();
          return handle;
        }

        function openAvatarPicker(rootEl, avatarEl) {
          const modal = document.getElementById('add-avatar-modal');
          const backdrop = document.getElementById('add-avatar-modal-backdrop');
          const closeBtn = document.getElementById('add-avatar-modal-close');
          const input = document.getElementById('add-avatar-url');
          const useBtn = document.getElementById('add-avatar-url-use');
          const grid = document.getElementById('add-avatar-grid');
          const err = document.getElementById('add-avatar-error');

          if (!modal || !backdrop || !closeBtn || !input || !useBtn || !grid || !err) {
            return;
          }

          function showError(msg) {
            err.textContent = String(msg || '');
            err.style.display = err.textContent ? 'block' : 'none';
          }

          function hide() {
            modal.style.display = 'none';
            backdrop.style.display = 'none';
            showError('');
          }

          function show() {
            modal.style.display = 'flex';
            backdrop.style.display = 'block';
            try {
              input.focus();
              input.select();
            } catch (e) {}
          }

          function useUrl(url) {
            url = String(url || '').trim();
            if (!url) return showError('请输入头像链接，或从下方头像库点选。');
            setAvatar(avatarEl, url);
            hide();
          }

          // 填充输入框为当前头像（若有）
          try {
            const current = String(avatarEl.getAttribute('data-add-avatar-url') || '').trim();
            input.value = current;
          } catch (e) {}

          // 渲染头像库
          try {
            const { randomAvatars } = getPhoneData();
            grid.innerHTML = '';
            const frag = document.createDocumentFragment();
            if (!randomAvatars.length) {
              showError('头像库为空（phone_data.randomAvatars 未配置）。');
            }
            for (let i = 0; i < randomAvatars.length; i++) {
              const url = String(randomAvatars[i] || '').trim();
              if (!url) continue;
              const btn = document.createElement('button');
              btn.type = 'button';
              btn.className = 'add-avatar-item';
              btn.title = url;
              const img = document.createElement('img');
              img.src = url;
              img.loading = 'lazy';
              img.decoding = 'async';
              btn.appendChild(img);
              btn.addEventListener('click', function () {
                setAvatar(avatarEl, url);
                hide();
              });
              frag.appendChild(btn);
            }
            grid.appendChild(frag);
          } catch (e) {
            showError('无法读取头像库（phone_data.randomAvatars）。');
          }

          // 绑定关闭/使用
          backdrop.onclick = hide;
          closeBtn.onclick = hide;
          useBtn.onclick = function () {
            showError('');
            useUrl(input.value);
          };
          input.onkeydown = function (e) {
            if (e.key === 'Enter') {
              e.preventDefault();
              showError('');
              useUrl(input.value);
            }
            if (e.key === 'Escape') {
              e.preventDefault();
              hide();
            }
          };

          show();
        }

        function commitAdd(rootEl, btnEl) {
          const name = String(rootEl.getAttribute('data-add-name') || '').trim();
          const handle = normalizeHandle(rootEl.getAttribute('data-add-handle') || '');
          const styleEl = rootEl.querySelector('.add-style');
          const onlineStyle = String((styleEl && styleEl.textContent) || '').trim();

          if (!name) return;
          if (typeof api.insertOrAssignVariables !== 'function') {
            toast('无法写入角色变量：未找到 insertOrAssignVariables（请确认 TavernHelper 可用）', 'error');
            return;
          }

          const vars = safeGetCharVars();
          let phoneData = (vars && vars.phone_data) || {};
          if (typeof phoneData === 'string') {
            try {
              phoneData = JSON.parse(phoneData);
            } catch (e) {
              phoneData = {};
            }
          }
          const characters = Array.isArray(phoneData.characters) ? phoneData.characters.slice() : [];

          // 去重：真实姓名/网名 双向匹配
          let exists = false;
          for (let i = 0; i < characters.length; i++) {
            const c = characters[i] || {};
            const n = String(c.name || '').trim();
            const nn = String(c.nickname || '').trim();
            if (name && (n === name || nn === name)) {
              exists = true;
              break;
            }
            if (handle && (n === handle || nn === handle)) {
              exists = true;
              break;
            }
          }
          if (exists) {
            btnEl.disabled = true;
            btnEl.innerHTML = '<i class="fas fa-check" aria-hidden="true"></i>已在角色列表';
            return;
          }

          const avatarEl = rootEl.querySelector('[data-add-avatar="1"]');
          let avatarUrl = '';
          if (avatarEl) avatarUrl = String(avatarEl.getAttribute('data-add-avatar-url') || '').trim();
          if (!avatarUrl) avatarUrl = getAvatarUrlDefault(name);

          const backgrounds = Array.isArray(phoneData.backgrounds) ? phoneData.backgrounds : [];

          const id = 'char_' + Math.random().toString(16).slice(2, 10);
          const newChar = {
            id: id,
            name: name,
            avatar: avatarUrl || '',
            nickname: handle || '',
            chatBg: pickBackground(backgrounds, name, 0),
            dynamicBg: pickBackground(backgrounds, name, 1),
            onlineStyle: onlineStyle || '',
          };

          characters.push(newChar);
          const updatedPhoneData = Object.assign({}, phoneData, { characters: characters });
          const ok = safeInsertCharVars({ phone_data: updatedPhoneData });
          if (!ok) {
            toast('添加失败：写入角色变量失败（请检查控制台报错）', 'error');
            return;
          }

          try {
            const verifyVars = safeGetCharVars();
            let verifyPhoneData = (verifyVars && verifyVars.phone_data) || {};
            if (typeof verifyPhoneData === 'string') verifyPhoneData = JSON.parse(verifyPhoneData);
            const verifyChars = Array.isArray(verifyPhoneData.characters) ? verifyPhoneData.characters : [];
            const found = findByName(verifyChars, name) || (handle ? findByName(verifyChars, handle) : null);
            if (!found) {
              toast(
                '已请求写入，但未在 phone_data.characters 中找到新增项（可能未选中角色卡/写入被拦截）',
                'warning',
              );
            }
          } catch (e) {}

          btnEl.disabled = true;
          btnEl.innerHTML = '<i class="fas fa-check" aria-hidden="true"></i>已添加';
          toast('已添加 ' + name, 'success');
        }

        document.addEventListener('DOMContentLoaded', function () {
          const rootEl = document.querySelector('[data-add-root="1"]');
          if (!rootEl) return;

          const name = String(rootEl.getAttribute('data-add-name') || '').trim();
          const avatarEl = rootEl.querySelector('[data-add-avatar="1"]');
          if (avatarEl) setAvatar(avatarEl, getAvatarUrlDefault(name));

          const onPick = function () {
            try {
              openAvatarPicker(rootEl, avatarEl);
            } catch (e) {
              console.warn('[add] pick avatar failed', e);
            }
          };

          if (avatarEl) {
            avatarEl.addEventListener('click', onPick);
            avatarEl.addEventListener('keydown', function (e) {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                onPick();
              }
            });
          }

          const btnEl = rootEl.querySelector('[data-add-commit="1"]');
          if (btnEl) {
            btnEl.addEventListener('click', function () {
              try {
                commitAdd(rootEl, btnEl);
              } catch (e) {
                console.warn('[add] commit failed', e);
                try {
                  btnEl.disabled = false;
                } catch (e2) {}
              }
            });
          }
        });
      })();
    </script>
  </body>
</html>
