                     if (tableName === TAB_DASHBOARD) {
                         $('#acu-data-area').css({height: '60vh', maxHeight: '95vh'});
                     } else {
                         $('#acu-data-area').css({height: '60vh', maxHeight: '95vh'});
                     }
